        "Използва се и за фанатично увлечение: von der Arbeit besessen sein, wie besessen arbeiten (работя като обсебен).",
        "Внимавай: besessen е и причастие на besitzen (притежавам): Er hat ein Haus besessen. Това е друга употреба; тази карта е за прилагателното обсебен."
