        "Глаголът е възвратен, с предлога über + винителен падеж: sich über etwas verwundern. Форми: ich verwundere mich, er verwundert sich, verwunderte sich, hat sich verwundert. Често следва и подчинено изречение с dass: sich darüber verwundern, dass …",
